css:
.parent {
  display: flex;
  justify-content: center;
  height: 1060px;
  align-items: center;
  transition: all 0.4s;
}

.square {
  background-color: rgba(228, 34, 16, 0.87);
  height: 50px;
  width: 50px;
  animation: rayan 1.2s infinite;
}

.circle {
  margin-left: 20px;
  height: 50px;
  width: 50px;
  background-color: rgba(228, 34, 16, 0.87);
  border-radius: 50%;
  animation: rayan 1.2s infinite;
  animation-delay: .4s;
}

@keyframes rayan {
  100% {
    background-color: rgb(0, 0, 0);
  }
}
